"""Private topology bridge from canonical editable Sections to Street views."""


def bind(compiled, layout, label):
    """Copy the original source topology, adding disposable source lookups.

    This private mesh is never an editable source or a solved surface. GN
    replaces its positions and dimensions from the canonical source collection.
    The canonical authoring order is specified by Blosm's PortSourceLayout.
    """
    reference=compiled.sources
    if len(reference.vertices)!=len(layout.controls) or len(reference.edges)!=len(layout.edges):
        raise ValueError('Canonical source layout differs from the original solver view')
    if tuple(e.section_id for e in layout.edges)!=tuple(a.value for a in reference.attributes['st_section_id'].data):
        raise ValueError('Canonical source layout changed original Section order')
    mesh=reference.copy();mesh.name=label+' private original Street view'
    roles={}
    for edge in layout.edges:
        roles.setdefault(edge.first,1);roles[edge.last]=2
    # An interior Section control is both a preceding edge's end and the
    # following edge's start, whereas separate Section ends retain 2 and 1.
    starts={e.first for e in layout.edges};ends={e.last for e in layout.edges}
    for at in starts & ends:roles[at]=0
    fields=[('_pv_vertex','POINT',[r.vertex for r in layout.controls]),
        ('_pv_alias','POINT',[r.alias for r in layout.controls]),
        ('_pv_role','POINT',[roles[r.vertex] for r in layout.controls]),
        ('_pv_edge','EDGE',[r.edge for r in layout.edges]),
        ('_pv_first','EDGE',[r.first for r in layout.edges]),
        ('_pv_last','EDGE',[r.last for r in layout.edges])]
    for name,domain,values in fields:
        mesh.attributes.new(name,'INT',domain).data.foreach_set('value',values)
    return mesh
